INSERT INTO `food` (`id`, `res_id`, `cat_id`, `name`, `price`, `main_image`, `summary`, `stock`, `status`, `total_count`, `view_count`, `comment_count`, `updated_time`, `created_time`) VALUES
(1, 2, 2, '鱼香肉丝', '10.00', 'food/7d6b640108b047a1997616ebebdbc916.jpg', '<p>鱼香肉丝是川菜中的一道名品，主要是用鲫鱼腌制的泡辣椒炒制猪里脊肉丝而成，以此将肉丝炒出鱼香味，故而叫鱼香肉丝。</p>', 1142, 1, 208, 0, 0, '2022-02-23 14:31:27', '2020-05-05 00:46:34'),
(2, 2, 2, '水煮肉片', '15.00', 'food/68c608acf57a42d19d6b9814e454bf1a.jpg', '<p>水煮肉片是一道地方新创名菜，起源于自贡，发扬于西南，属于川菜中著名的家常菜。因肉片未经划油，以水煮熟故名水煮肉片。</p>', 1148, 1, 102, 0, 0, '2022-02-20 09:25:41', '2020-05-05 00:48:37'),
(3, 1, 1, '农家小炒肉', '10.00', 'food/19c25a1b46054ad2828b02f31ddebb6c.jpg', '<p>小炒肉是湖南省一道常见的特色传统名菜，属于湘菜系。麻辣鲜香，口味滑嫩。制作原料主要是五花肉和青椒、红椒等。</p>', 1186, 1, 361, 0, 0, '2022-02-23 14:16:44', '2020-05-05 00:50:37'),
(4, 1, 1, '剁椒鱼头', '20.00', 'food/9fb52ddd5b4746038394fe743fce5cce.jpg', '<p>剁椒鱼头是湖南省的传统名菜，属于湘菜系。通常以鳙鱼鱼头、剁椒为主料，配以豉油、姜、葱、蒜等辅料蒸制而成。菜品色泽红亮、味浓、肉质细嫩。肥而不腻、口感软糯、鲜辣适口。</p>', 1127, 1, 249, 0, 0, '2022-02-23 12:54:19', '2020-05-05 00:53:03'),
(5, 3, 3, '白切鸡', '10.00', 'food/4bb33aca1e4d4935ac03fda7ee2ab409.jpg', '<p>白切鸡又叫白斩鸡，是中国八大菜之一粤菜系鸡肴中的一种，始于清代的民间酒店。</p><p>白切鸡通常选用细骨农家鸡与沙姜、蒜茸等食材，慢火煮浸后，晾干切块。</p><p>成菜后，色洁白带油黄，皮爽肉滑骨香，清淡鲜美。</p><p><br/></p>', 1137, 1, 148, 0, 0, '2022-02-23 14:32:24', '2020-05-05 00:55:40'),
(6, 3, 3, '木瓜炖雪蛤', '20.00', 'food/433d50e061f54c469083ade89205f2b1.jpg', '<p>木瓜炖雪蛤是一道美味可口的传统名点，属于粤菜系。以木瓜和雪蛤为主要食材，属粤式甜品，润肤养颜，营养价值丰富。主要材料有木瓜、雪蛤油、鲜奶、水等。</p>', 1120, 1, 68, 0, 0, '2022-02-20 09:25:41', '2020-05-05 00:57:31'),
(7, 4, 4, '飞龙汤', '15.00', 'food/fe26d84de2a84c1fa286924fcc1297dc.jpg', '<p>飞龙又名榛鸡是黑龙江省的名菜之一，属于龙江菜系，产于兴安岭。飞龙汤是将榛鸡脱毛去掉内脏后，用高汤煮熟即可，汤中不需放任何调料以保持汤原汁原味。飞龙汤肉质鲜美，营养丰富，适合用作滋补汤品。</p>', 1126, 1, 99, 0, 0, '2022-02-20 09:01:57', '2020-05-05 00:59:53'),
(8, 5, 5, '糖醋鲤鱼', '15.00', 'food/620858717a704b5d8bfb950f5036a68a.jpg', '<p>店长推荐<br/></p>', 1150, 1, 231, 0, 0, '2020-05-15 08:30:26', '2020-05-15 08:30:26');
