INSERT INTO `yzm_page` (`catid`, `title`, `pagedir`, `keywords`, `description`, `content`, `updatetime`) VALUES
(4, '关于我们', 'guanyuwomen', '', '', '<p>YzmCMS是一款轻量级开源的内容管理系统，采用OOP方式自主开发的框架（YZMPHP）。系统易扩展，是一款高效开源的内容管理系统。系统基于PHP+Mysql架构，可运行在Linux、Windows、MacOSX、Solaris等各种平台上，程序采用MVC设计模式，前台采用DIV+CSS设计，遵循WEB标准,兼容各种浏览器(包括IE6)，源码简洁清晰，完全采用PHP5面向对象设计，功能简单易懂具有良好的用户体验，稳定性好、扩展性及安全性强。</p><p><br/></p><p>我之所以开发这个CMS，是因为我对IT互联网技术的兴趣，程序开发纯属于个人爱好兴趣，不然也不可能坚持这么多年，由于个人时间精力有限，程序中可能会存在一些问题，欢迎大家及时反馈。<br/></p>', 1485088083);
